#include <bits/stdc++.h>
using namespace std;

const int mod = 998244353;

long long powMod(long long base, long long exp) {
    long long res = 1;
    long long cur = base % mod;
    while (exp > 0) {
        if (exp & 1) res = res * cur % mod;
        cur = cur * cur % mod;
        exp >>= 1;
    }
    return res;
}

long long getCombination(const vector<long long>& fac, const vector<long long>& inv, int n, int m) {
    return fac[n] * inv[m] % mod * inv[n - m] % mod;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    string line;
    getline(cin, line);
    istringstream iss(line);
    int n;
    long long k;
    iss >> n >> k;

    vector<long long> factorials(200001);
    vector<long long> inverses(200001);
    factorials[0] = inverses[0] = 1;
    for (int i = 1; i <= 200000; i++) {
        factorials[i] = factorials[i - 1] * i % mod;
        inverses[i] = inverses[i - 1] * powMod(i, mod - 2) % mod;
    }

    if (k >= n) {
        cout << 0 << "\n";
        return 0;
    }
    if (k == 0) {
        cout << factorials[n] << "\n";
        return 0;
    }

    int m = n - (int)k;
    long long total = 0;
    for (int i = 0; i <= m; i++) {
        long long comb = getCombination(factorials, inverses, m, i);
        long long term = powMod(m - i, n);
        if (i % 2 == 0) {
            total = (total + comb * term % mod) % mod;
        } else {
            total = (total - comb * term % mod + mod) % mod;
        }
    }
    long long result = 2LL * factorials[n] % mod * inverses[n - m] % mod * total % mod * inverses[m] % mod;
    cout << result << "\n";

    return 0;
}
